package com.paymentplatform.transfer_service.api;
import com.paymentplatform.transfer_service.domain.*;import com.paymentplatform.transfer_service.security.ServiceActor;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController public class TransferController {
 private final TransferWorkflow workflow;private final TransferStore store;public TransferController(TransferWorkflow workflow,TransferStore store){this.workflow=workflow;this.store=store;}
 @PostMapping("/v1/transfers") ResponseEntity<?> create(@AuthenticationPrincipal Jwt jwt,@RequestHeader("Idempotency-Key") @Pattern(regexp="[A-Za-z0-9][A-Za-z0-9._:-]{0,127}") String key,@Valid @RequestBody TransferRequest request){var result=workflow.accept(jwt.getClaimAsString("integrator_id"),ServiceActor.requireService(jwt),key,request);return response(result.response(),result.replayed());}
 @PostMapping("/v1/transfers/{id}/cancellation") ResponseEntity<?> cancel(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID id){return response(store.view(workflow.cancel(jwt.getClaimAsString("integrator_id"),ServiceActor.requireService(jwt),id)),true);}
 @GetMapping("/v1/transfers/{id}") ResponseEntity<?> get(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID id){ServiceActor.requireService(jwt);return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(store.view(store.get(jwt.getClaimAsString("integrator_id"),id)));}
 @GetMapping("/v1/transfers") ResponseEntity<?> list(@AuthenticationPrincipal Jwt jwt,@RequestParam UUID walletId,@RequestParam(required=false) UUID after,@RequestParam(defaultValue="50") @Min(1) @Max(100) int limit){ServiceActor.requireService(jwt);var rows=store.list(jwt.getClaimAsString("integrator_id"),walletId,after,limit);var items=List.copyOf(rows.subList(0,Math.min(limit,rows.size())));return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(new Page(items,rows.size()>limit?items.getLast().id():null));}
 @PostMapping("/internal/v1/transfers/{id}/resume") ResponseEntity<?> resume(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID id){worker(jwt);return response(store.view(workflow.resume(jwt.getClaimAsString("integrator_id"),id)),true);}
 @GetMapping("/internal/v1/transfers/recoverable") ResponseEntity<?> recoverable(@AuthenticationPrincipal Jwt jwt,@RequestParam(required=false) UUID after,@RequestParam(defaultValue="50") @Min(1) @Max(100) int limit){worker(jwt);return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(store.recoverable(jwt.getClaimAsString("integrator_id"),after,limit));}
 private void worker(Jwt jwt){if(!"transfer-service".equals(ServiceActor.requireService(jwt)))throw new ApiException(HttpStatus.FORBIDDEN,"WORKER_REQUIRED","The provisioned transfer service principal is required.");}
 private ResponseEntity<?> response(TransferStore.View view,boolean replayed){return ResponseEntity.status(view.status().equals("CANCELLED")?200:view.status().equals("COMPLETED")?201:view.status().equals("REJECTED")?422:202).cacheControl(CacheControl.noStore()).header("Location","/v1/transfers/"+view.id()).header("Idempotency-Replayed",Boolean.toString(replayed)).body(view);}
 public record Page(List<TransferStore.View> items,UUID nextAfter){}
}
